package com.muntinlupa.barangay_ease.ai;

/** Fixed, pre-written guidance. Never generated by the AI so it is always correct and available. */
public final class SafetyMessages {

    private SafetyMessages() { }

    public static final String IMMEDIATE =
            "This looks like an emergency. Please call 911 right now, or go to the nearest hospital or "
          + "fire station. Do not wait for an online reply. "
          + "Mukhang emergency ito. Tumawag agad sa 911 o pumunta sa pinakamalapit na ospital o himpilan "
          + "ng bumbero. Huwag nang hintayin ang sagot dito.";

    public static final String CRITICAL =
            "This is a serious case that cannot be handled through the online complaint form. Please go to "
          + "your nearest Barangay Hall, the PNP station, or the PNP Women and Children Protection Desk "
          + "(WCPD) right away. If you or someone else is in danger, call 911 now. "
          + "Ang kasong ito ay seryoso at hindi maaaring i-file online. Pumunta agad sa pinakamalapit na "
          + "Barangay Hall, istasyon ng PNP, o Women and Children Protection Desk (WCPD). Kung may "
          + "panganib, tumawag sa 911.";

    public static final String SELF_HARM =
            "I'm really sorry you're going through this, and you don't have to face it alone. If you are "
          + "thinking about hurting yourself or you are in danger right now, please call 911 or go to the "
          + "nearest hospital or barangay hall, and ask someone you trust to stay with you. "
          + "Pasensya na at pinagdadaanan mo ito. Hindi ka nag-iisa. Kung may balak kang saktan ang sarili "
          + "mo o nasa panganib ka ngayon, tumawag sa 911 o pumunta sa pinakamalapit na ospital o barangay "
          + "hall at magpasama sa taong pinagkakatiwalaan mo.";

    static String forScreen(EmergencyKeywordScreen.Result r) {
        if (r.level() == EmergencyKeywordScreen.Level.CRITICAL) return CRITICAL;
        if (r.selfHarm()) return SELF_HARM;
        return IMMEDIATE;
    }
}
